  WHERE u.usage_date >= dateadd(day, -({{ w }} + {{ param('cost_daily_spikes', 'baseline_days', 14) }}), {{ audit_today() }})
    AND u.usage_date <  {{ audit_today() }}
  GROUP BY u.workspace_id, u.billing_origin_product, u.usage_date, u.sku_name
),
daily AS (
