  WHERE usage_date >= dateadd(day, -{{ w }}, {{ audit_today() }})
  QUALIFY ROW_NUMBER() OVER (
    PARTITION BY workspace_id, billing_origin_product, usage_date ORDER BY sku_cost DESC, sku_name
  ) <= 3
),
drivers AS (
